#include "model/arch_qwen.hpp"
#include <chrono>
#include <iomanip>
#include <iostream>
#include <map>
#ifdef LLMX_COMPARE_REFERENCE
#include "ggml-cpu.h"
#endif
using Clock=std::chrono::steady_clock;
struct Job {
    size_t nin=0,bytes=0;
    std::vector<backend::Projection> projections;
    std::vector<float> x;
    std::vector<std::vector<float>> output;
#ifdef LLMX_COMPARE_REFERENCE
    ggml_context* ctx=nullptr;
    ggml_cgraph* graph=nullptr;
    ggml_cplan plan{};
    std::vector<uint8_t> work;
    ~Job(){if(ctx)ggml_free(ctx);}
#endif
};
int main(int argc,char**argv) {
    if(argc!=3)return 2;
    auto weights=gguf::read_gguf(argv[1]);auto cfg=infer::load_config(weights);
    int threads=std::stoi(argv[2]);if(threads<1||threads>64)return 2;
    std::map<std::string,size_t> index;for(size_t i=0;i<weights.tensors.size();++i)index[weights.tensors[i].name]=i;
#ifdef LLMX_COMPARE_REFERENCE
    ggml_cpu_init();auto params=ggml_threadpool_params_default(threads);auto* pool=ggml_threadpool_new(&params);
    if(!pool)return 3;
#else
    quant::register_builtins();backend::CpuBackend cpu;cpu.set_threads(threads);
#endif
    for(const std::string kind:{"qkv","attn_output","gate_up","ffn_down","output"}) {
        std::vector<std::unique_ptr<Job>> jobs;
        for(int layer=0;layer<(kind=="output"?1:cfg.n_layer);++layer) {
            std::string pre="blk."+std::to_string(layer)+".";
            std::vector<std::string> names;
            if(kind=="qkv")names={pre+"attn_q.weight",pre+"attn_k.weight",pre+"attn_v.weight"};
            if(kind=="attn_output")names={pre+"attn_output.weight"};
            if(kind=="gate_up")names={pre+"ffn_gate.weight",pre+"ffn_up.weight"};
            if(kind=="ffn_down")names={pre+"ffn_down.weight"};
            if(kind=="output")names={index.count("output.weight")?"output.weight":"token_embd.weight"};
            auto job=std::make_unique<Job>();job->output.resize(names.size());
            for(size_t j=0;j<names.size();++j) {
                size_t i=index.at(names[j]);auto& t=weights.tensors[i];if(t.ne.size()!=2)return 4;
                if(j==0)job->nin=size_t(t.ne[0]);else if(job->nin!=t.ne[0])return 5;
                job->output[j].resize(size_t(t.ne[1]));job->bytes+=weights.tensor_bytes(i);
                job->projections.push_back({t.type,weights.tensor_data(i),job->output[j].data(),size_t(t.ne[1])});
            }
            job->x.resize(job->nin);for(size_t i=0;i<job->nin;++i)job->x[i]=std::sin(float(i)*0.019f+float(layer)*0.113f);
#ifdef LLMX_COMPARE_REFERENCE
            const size_t graph_size=16;
            job->ctx=ggml_init({ggml_tensor_overhead()*8+ggml_graph_overhead_custom(graph_size,false)+1024,nullptr,true});
            if(!job->ctx)return 6;
            auto* x=ggml_new_tensor_2d(job->ctx,GGML_TYPE_F32,int64_t(job->nin),1);x->data=job->x.data();
            job->graph=ggml_new_graph_custom(job->ctx,graph_size,false);
            for(auto& p:job->projections) {
                auto* w=ggml_new_tensor_2d(job->ctx,ggml_type(p.type),int64_t(job->nin),int64_t(p.rows));w->data=const_cast<uint8_t*>(p.data);
                auto* y=ggml_mul_mat(job->ctx,w,x);y->data=p.out;ggml_build_forward_expand(job->graph,y);
            }
            job->plan=ggml_graph_plan(job->graph,threads,pool);job->work.resize(job->plan.work_size);job->plan.work_data=job->work.data();
#endif
            jobs.push_back(std::move(job));
        }
        auto execute=[&](Job& j) {
#ifdef LLMX_COMPARE_REFERENCE
            if(ggml_graph_compute(j.graph,&j.plan)!=GGML_STATUS_SUCCESS)throw std::runtime_error("graph failed");
#else
            auto& p=j.projections;
            if(p.size()==1)cpu.matmul(p[0].type,p[0].data,j.x.data(),p[0].out,j.nin,p[0].rows,1);
            else if(p.size()==2)cpu.matmul_group({p[0],p[1]},j.x.data(),j.nin,1);
            else cpu.matmul_group({p[0],p[1],p[2]},j.x.data(),j.nin,1);
#endif
        };
        for(int cycle=0;cycle<4;++cycle)for(auto& j:jobs)execute(*j);
        constexpr int cycles=64;auto start=Clock::now();
        for(int cycle=0;cycle<cycles;++cycle)for(auto& j:jobs)execute(*j);
        double ms=std::chrono::duration<double,std::milli>(Clock::now()-start).count();
        double sum=0;size_t bytes=0;for(auto& j:jobs){bytes+=j->bytes;for(auto& out:j->output)for(float v:out){if(!std::isfinite(v))return 7;sum+=v;}}
        std::cout<<std::setprecision(12)<<"{\"kind\":\""<<kind<<"\",\"threads\":"<<threads<<",\"jobs\":"<<jobs.size()<<",\"cycles\":"<<cycles<<",\"bytes_per_cycle\":"<<bytes<<",\"ms\":"<<ms<<",\"checksum\":"<<sum<<",\"nin\":"<<jobs[0]->nin<<",\"rows\":[";
        bool first=true;for(auto& p:jobs[0]->projections){if(!first)std::cout<<",";first=false;std::cout<<p.rows;}std::cout<<"]}\n";
    }
#ifdef LLMX_COMPARE_REFERENCE
    ggml_threadpool_free(pool);
#endif
}

