#include "model/arch_qwen.hpp"
#include <chrono>
#include <iomanip>
#include <iostream>
#include <map>
#include <sstream>
using Clock=std::chrono::steady_clock;
struct Stats {size_t calls=0;double ms=0;};
class ProfileBackend : public backend::CpuBackend {
public:
    bool enabled=false,nested=false;
    std::map<std::string,Stats> stats;
    void add(const std::string& name, Clock::time_point t) {
        double ms=std::chrono::duration<double,std::milli>(Clock::now()-t).count();
        auto& s=stats[name];++s.calls;s.ms+=ms;
    }
    void matmul(uint32_t type,const uint8_t* data,const float* X,float* Y,size_t nin,size_t nout,size_t batch) override {
        if(!enabled||nested) {CpuBackend::matmul(type,data,X,Y,nin,nout,batch);return;}
        std::string key="matmul/type"+std::to_string(type)+"/"+std::to_string(nin)+"x"+std::to_string(nout)+"/batch"+std::to_string(batch);
        auto t=Clock::now();CpuBackend::matmul(type,data,X,Y,nin,nout,batch);add(key,t);
    }
    void matmul_group(std::initializer_list<backend::Projection> p,const float* X,size_t nin,size_t batch) override {
        if(!enabled) {CpuBackend::matmul_group(p,X,nin,batch);return;}
        std::string key="group/"+std::to_string(nin)+"x";
        for(auto& v:p) key+=std::to_string(v.rows)+"t"+std::to_string(v.type)+"+";
        key+="/batch"+std::to_string(batch);
        nested=true;auto t=Clock::now();CpuBackend::matmul_group(p,X,nin,batch);add(key,t);nested=false;
    }
    void attention(const float* Q,const float* K,const float* V,float* out,int nh,int nk,int hd,int past,int batch) override {
        if(!enabled) {CpuBackend::attention(Q,K,V,out,nh,nk,hd,past,batch);return;}
        auto t=Clock::now();CpuBackend::attention(Q,K,V,out,nh,nk,hd,past,batch);add("attention",t);
    }
};
int main(int argc,char**argv) {
    if(argc!=4)return 2;
    auto weights=gguf::read_gguf(argv[1]);auto backend=std::make_shared<ProfileBackend>();
    infer::Model model(weights,backend);int nt=std::stoi(argv[3]);model.set_threads(nt);model.set_ubatch(128);
    std::ifstream input(argv[2]);std::vector<uint32_t> ids;uint32_t id;while(input>>id)ids.push_back(id);if(ids.size()!=247)return 3;
    std::vector<uint32_t> prompt(ids.begin(),ids.begin()+215);std::vector<float> logits;
    for(int run=0;run<3;++run) {
        model.reset();backend->enabled=false;logits=model.prefill(prompt);backend->stats.clear();backend->enabled=run>0;
        auto start=Clock::now();for(size_t i=215;i<247;++i)logits=model.step(ids[i]);
        double total=std::chrono::duration<double,std::milli>(Clock::now()-start).count();backend->enabled=false;
        double sum=0;for(float v:logits){if(!std::isfinite(v))return 4;sum+=v;}
        if(run==0)continue;
        std::cout<<std::setprecision(12)<<"{\"run\":"<<run<<",\"threads\":"<<nt<<",\"total_ms\":"<<total<<",\"logit_sum\":"<<sum<<",\"ops\":[";
        bool first=true;for(auto& entry:backend->stats){if(!first)std::cout<<",";first=false;std::cout<<"{\"name\":\""<<entry.first<<"\",\"calls\":"<<entry.second.calls<<",\"ms\":"<<entry.second.ms<<"}";}
        std::cout<<"]}\n";
    }
}

