#include "inference/perplexity.hpp"
#include <fstream>
#include <iomanip>
#include <iostream>
#include <cstring>
int main(int argc,char** argv) {
    if(argc!=4)return 2;
    auto weights=gguf::read_gguf(argv[1]);infer::Model model(weights);model.set_ubatch(128);
    std::ifstream input(argv[2]);std::vector<uint32_t> ids;uint32_t id;while(input>>id)ids.push_back(id);if(ids.size()!=247)return 3;
    std::vector<uint32_t> prompt(ids.begin(),ids.begin()+215);
    std::vector<std::vector<float>> reference;
    double reference_nll=0;
    for(int nt:{6,1,2,4,8,16}) {
        model.set_threads(nt);model.reset();auto logits=model.prefill(prompt);size_t checked=0;
        for(size_t step=0;step<33;++step) {
            if(step)logits=model.step(ids[214+step]);
            for(float v:logits)if(!std::isfinite(v))return 4;
            if(nt==6)reference.push_back(logits);
            else if(logits.size()!=reference[step].size()||std::memcmp(logits.data(),reference[step].data(),logits.size()*sizeof(float))) {
                std::cerr<<"full logits differ at threads="<<nt<<" step="<<step<<"\n";return 5;
            }
            checked+=logits.size();
        }
        auto result=infer::perplexity(model,ids);
        if(nt==6)reference_nll=result.mean_nll();
        else if(result.mean_nll()!=reference_nll)return 6;
        if(result.used_tokens!=247||result.scored_tokens!=246||result.chunks!=1||!std::isfinite(result.mean_nll()))return 7;
        std::cout<<std::setprecision(17)<<"{\"threads\":"<<nt<<",\"vectors\":33,\"values\":"<<checked<<",\"identical_to_threads_6\":true,\"mean_nll\":"<<result.mean_nll()<<",\"scored_tokens\":"<<result.scored_tokens<<"}\n"<<std::flush;
    }
    std::ofstream output(argv[3],std::ios::binary);for(auto& v:reference)output.write(reinterpret_cast<const char*>(v.data()),std::streamsize(v.size()*sizeof(float)));
    return output?0:8;
}

